<?php

namespace BitApps\Social\HTTP\Services\Schedule;

use BitApps\Social\Config;
use BitApps\Social\Deps\BitApps\WPKit\Hooks\Hooks;
use BitApps\Social\Model\Schedule;
use BitApps\Social\Utils\Common;
use BitApps\Social\Utils\PublishLock;

class CustomSchedule
{
    use Common;

    /**
     * Marks a schedule row as generated by delayed auto-post rather than by a
     * user picking a time. Stored in config.settings.source.
     */
    public const AUTO_POST_SOURCE = 'auto_post';

    /**
     * Legacy auto-post rows (created before AUTO_POST_SOURCE existed) are only
     * identifiable by the name AutoPostService gives them.
     */
    public const AUTO_POST_NAME_PREFIX = 'Auto Post - Post ID:';

    /**
     * How late a post may be and still get published. Both start at an hour;
     * they stay separate settings because the two kinds of post are worth
     * different amounts of lateness on different sites, and each is overridable
     * from Cron Setup (Pro) and by its own filter.
     *
     * An hour rather than a tick's worth of slack, and the same number with or
     * without a licence, because of what these sites actually look like: plenty
     * of them have no real server cron and only tick when a visitor lands, and
     * plenty more run wp-cron.php from a system crontab every fifteen minutes.
     * Every one of those posts published — late — before this reaper existed, so
     * a window tight enough to be "punctual" would read to those users as the
     * update having stopped their posting. What Pro adds is control over the
     * window (including 0 for "publish however late"), not the right to be late.
     */
    public const DEFAULT_AUTOPOST_WINDOW = ['every' => 1, 'unit' => 'hour'];

    public const DEFAULT_SCHEDULE_WINDOW = ['every' => 1, 'unit' => 'hour'];

    /**
     * Units offered for the windows above.
     */
    public const WINDOW_UNITS = ['minute', 'hour', 'day'];

    /**
     * Upper bound for a window, whatever unit it is expressed in.
     */
    public const MAX_WINDOW_SECONDS = 30 * DAY_IN_SECONDS;

    public const DELAY_UNITS = [
        'second' => 1,
        'minute' => 60,
        'hour'   => 3600,
        'day'    => 86400,
        'week'   => 604800,
        'month'  => 2592000,
        'year'   => 31536000,
    ];

    protected $schedules = [];

    public function __construct($schedules)
    {
        $this->schedules = $schedules;
    }

    public function register()
    {
        Hooks::addFilter('cron_schedules', [$this, 'addCustomInterval']);

        foreach ($this->schedules as $schedule) {
            $config = $this->setScheduleConfig($schedule['config']);

            if ($schedule['status'] === Schedule::status['ACTIVE'] && $schedule['cron_status'] === Schedule::cronStatus['ACTIVE'] && $config) {
                $settings = isset($config['settings']) ? $config['settings'] : [];

                if (
                    $schedule['schedule_type'] === Schedule::scheduleType['SCHEDULE_SHARE']
                    || (
                        $schedule['schedule_type'] === Schedule::scheduleType['DIRECT_SHARE']
                        && isset($settings['repeat'])
                        && $settings['repeat'] === true
                    )
                ) {
                    $this->createScheduleEvent($schedule, $settings);
                }

                $this->restoreSingleEvent($schedule, $settings);
            }
        }
    }

    /**
     * Heal one-shot schedules that got stuck in ACTIVE ("In Progress").
     *
     * A non-recurring schedule (auto-post / share-now / non-repeat direct share)
     * runs from a single cron event. If that event never fired (WP-Cron behind)
     * or was consumed without completing, the row hangs in ACTIVE forever. Once
     * it is overdue past the threshold, mark it MISSED and clear any pending
     * (late) event so it does not post stale content — matching the "mark
     * missed, don't post" policy. Recurring schedules are left alone; they
     * reschedule themselves via register().
     *
     * Anything still inside its window is left for cron to publish late; see
     * missedThresholdFor() for how much lateness that is.
     */
    public function reapMissedSingleEvents()
    {
        $nowWallClock = strtotime(current_time('mysql'));
        $now = time();
        $reaperSince = self::reaperActiveSince();
        $missedIds = [];

        // How many pre-upgrade rows one sweep may heal. Filterable because the
        // right number depends on a database nobody here can see; 0 or less
        // turns the rationing off and heals the whole backlog in one request.
        $healCap = (int) apply_filters(Config::VAR_PREFIX . 'missed_heal_batch', 50);
        $healCap = $healCap > 0 ? $healCap : PHP_INT_MAX;
        $healed = 0;

        foreach ($this->schedules as $schedule) {
            if ((int) $schedule['status'] !== Schedule::status['ACTIVE']) {
                continue;
            }

            $config = $this->setScheduleConfig($schedule['config']);
            $settings = $config ? $config['settings'] : [];

            if ($this->isRecurringRow($schedule, $settings)) {
                continue;
            }

            $intendedAt = !empty($schedule['started_at'])
                ? $schedule['started_at']
                : (!empty($schedule['next_published_at']) ? $schedule['next_published_at'] : null);

            if (empty($intendedAt)) {
                continue;
            }

            $threshold = $this->missedThresholdFor($schedule, $settings);

            if ($threshold <= 0) {
                continue;
            }

            $eventTimestamp = $this->nextEventTimestamp($schedule['id']);

            // A pending event in the future means this schedule is not stuck —
            // it is queued and waiting.
            if ($eventTimestamp > $now) {
                continue;
            }

            if ($this->latenessOf($intendedAt, $eventTimestamp, $nowWallClock, $now) <= $threshold) {
                continue;
            }

            // A run that is happening right now looks exactly like one that
            // never happened: the event is gone and the row is still ACTIVE.
            // Ten accounts and a video upload can outlast the window, and
            // writing that run off mid-flight would log and email a miss for a
            // post that is in the middle of going out.
            if (PublishLock::isHeld($schedule['id'])) {
                continue;
            }

            // Rows whose slot predates this sweep are the backlog of everything
            // that ever got stuck — on a long-lived install that is a wall of
            // red the day they update, for posts nobody expects any more. Heal
            // the row so it stops reading "In Progress", but report only what
            // this version was actually watching.
            $isReportable = strtotime($intendedAt) >= $reaperSince;

            // Healing one of those rows costs a read, a write, and a rewrite of
            // the whole cron option — and an install that has been running for
            // years can have thousands of them, all landing in the first request
            // after the update, which is the one request that must not fall
            // over. So the backlog drains a few rows per sweep instead, over the
            // next handful of page loads. Only the silent healing is rationed: a
            // slot missed since the update is written off and reported the
            // moment it is found, however long the backlog behind it is.
            if (!$isReportable && $healed >= $healCap) {
                continue;
            }

            $stuck = Schedule::findOne(['id' => $schedule['id']]);
            if (empty($stuck)) {
                continue;
            }

            $stuck->update([
                'status'            => Schedule::status['MISSED'],
                'cron_status'       => Schedule::cronStatus['INACTIVE'],
                'ended_at'          => gmdate('Y-m-d H:i:s', current_time('timestamp')),
                'next_published_at' => null,
            ])->save();

            if ($isReportable) {
                // Written before the event is cleared, while the row still says
                // what it was going to post: without these the Logs screen has
                // nothing at all for a delayed auto-post that never ran, and the
                // post cannot be retried from there like every other failure.
                $this->logMissedSlot($schedule['id'], $intendedAt);
                $missedIds[] = $schedule['id'];
            } else {
                ++$healed;
            }

            $this->clearScheduleById($schedule['id']);
        }

        // One action for the whole sweep rather than one per row: a catch-up
        // after long downtime can write off many at once, and listeners (the Pro
        // email alert) should report that as a single message, not a flood.
        if (!empty($missedIds)) {
            $this->announceMissed($missedIds);
        }
    }

    /**
     * Drain a catch-up backlog gradually instead of all at once.
     *
     * WP-Cron runs every due event in a single request. After downtime that
     * means every overdue one-shot fires together — twenty posts hitting the
     * same platform in one second, which is what rate limits and spam
     * heuristics are built to catch. So the oldest one is left to run now and
     * the rest are pushed out at a fixed spacing, oldest first.
     *
     * Runs at plugins_loaded, which fires before wp-cron.php reads the ready
     * hooks, so re-queueing here takes effect for the very run that triggered
     * it. Must run AFTER reapMissedSingleEvents() — anything too old to publish
     * should be written off before we reserve a slot for it.
     */
    public function spaceOverdueBacklog()
    {
        $spacing = (int) apply_filters(Config::VAR_PREFIX . 'catchup_spacing', 5 * MINUTE_IN_SECONDS);
        if ($spacing <= 0) {
            return;
        }

        $now = time();
        $overdue = [];

        foreach ($this->schedules as $schedule) {
            if ((int) $schedule['status'] !== Schedule::status['ACTIVE']) {
                continue;
            }

            $config = $this->setScheduleConfig($schedule['config']);
            $settings = $config ? $config['settings'] : [];

            // Recurring schedules keep a repeating cron event; re-queueing one as
            // a single event would silently break its recurrence. Their late runs
            // are already handled by ScheduleInfo::isExecutionStale().
            if ($this->isRecurringRow($schedule, $settings)) {
                continue;
            }

            $timestamp = $this->nextEventTimestamp($schedule['id']);

            if (!$timestamp || $timestamp > $now) {
                continue;
            }

            $overdue[] = ['id' => $schedule['id'], 'timestamp' => $timestamp];
        }

        // One overdue event is not a burst — let it through untouched.
        if (\count($overdue) < 2) {
            return;
        }

        usort($overdue, static function ($a, $b) {
            return $a['timestamp'] <=> $b['timestamp'];
        });

        // The oldest keeps its slot and publishes on this run; the rest queue up
        // behind it. array_slice drops that first entry, so $position starts the
        // spacing at one interval out.
        foreach (\array_slice($overdue, 1) as $position => $event) {
            $actionHook = Config::VAR_PREFIX . $event['id'] . '_cron_exec';
            $hookArgument = ['schedule_id' => $event['id']];

            wp_unschedule_event($event['timestamp'], $actionHook, [$hookArgument]);
            wp_schedule_single_event($now + (($position + 1) * $spacing), $actionHook, [$hookArgument]);
        }
    }

    /**
     * Timestamp of a schedule's pending cron event, or 0 when none is queued.
     *
     * @param int $scheduleId
     *
     * @return int
     */
    public function nextEventTimestamp($scheduleId)
    {
        $actionHook = Config::VAR_PREFIX . $scheduleId . '_cron_exec';
        $hookArgument = ['schedule_id' => $scheduleId];

        return (int) wp_next_scheduled($actionHook, [$hookArgument]);
    }

    /**
     * A schedule generated by delayed auto-post, as opposed to one whose time
     * the user picked by hand (Share Now / scheduled share).
     *
     * @param array $schedule
     * @param array $settings config.settings for that row
     *
     * @return bool
     */
    public static function isAutoPostSchedule($schedule, $settings)
    {
        if (!empty($settings['source']) && $settings['source'] === self::AUTO_POST_SOURCE) {
            return true;
        }

        $name = isset($schedule['name']) ? (string) $schedule['name'] : '';

        return strpos($name, self::AUTO_POST_NAME_PREFIX) === 0;
    }

    public function createScheduleEvent($schedule, $settings)
    {
        if (empty($settings['post_interval_value']) || empty($settings['post_interval_type'])) {
            return;
        }

        $actionHook = Config::VAR_PREFIX . $schedule['id'] . '_cron_exec';
        $hookArgument['schedule_id'] = $schedule['id'];

        $wpNextPostTimeStamp = wp_next_scheduled($actionHook, [$hookArgument]);

        if ($wpNextPostTimeStamp) {
            return;
        }

        $wpTimeStamp = current_time('timestamp');

        $scheduleRunTime = time();

        $recurrence = Config::VAR_PREFIX . 'every_' . $settings['post_interval_value'] . '_' . $settings['post_interval_type'];

        if (!empty($schedule['started_at']) && strtotime($schedule['started_at']) > $wpTimeStamp) {
            $delay = strtotime($schedule['started_at']) - $wpTimeStamp;
            $scheduleRunTime = $scheduleRunTime + $delay;
        } elseif (!$wpNextPostTimeStamp) {
            $delay = self::getDelayInSeconds($settings['post_interval_value'], $settings['post_interval_type'], $scheduleRunTime);
            $scheduleRunTime = $scheduleRunTime + $delay;
        }

        wp_schedule_event($scheduleRunTime, $recurrence, $actionHook, [$hookArgument]);
    }

    public function addCustomInterval($schedules)
    {
        foreach ($this->schedules as $schedule) {
            if ($schedule['status'] === Schedule::status['ACTIVE'] && $schedule['cron_status'] === Schedule::cronStatus['ACTIVE']) {
                $config = \is_string($schedule['config']) ? json_decode($schedule['config'], true) : $schedule['config'];
                $settings = isset($config['settings']) ? $config['settings'] : [];
                if (empty($settings)) {
                    continue;
                }

                if (!empty($settings['post_interval_value']) && !empty($settings['post_interval_type'])) {
                    $scheduleName = Config::VAR_PREFIX . 'every_' . $settings['post_interval_value'] . '_' . $settings['post_interval_type'];
                    // translators: 1: interval value, 2: interval type (e.g. minute, hour, day)
                    $displayName = \sprintf(esc_html__('Every %1$s %2$s (Bit Social)', 'bit-social'), $settings['post_interval_value'], $settings['post_interval_type']);
                    $schedules[$scheduleName] = [
                        'interval' => self::getDelayInSeconds($settings['post_interval_value'], $settings['post_interval_type']),
                        'display'  => $displayName,
                    ];
                }
            }
        }

        return $schedules;
    }

    public static function getDelayInSeconds($value, $unit, $fromTimestamp = null)
    {
        if ($unit === 'month' || $unit === 'year') {
            $from = $fromTimestamp ?? time();
            $future = strtotime("+{$value} {$unit}", $from);

            return $future - $from;
        }

        return $value * self::DELAY_UNITS[$unit];
    }

    /**
     * Pulls one window out of the stored settings.
     *
     * Also understands the earlier hours-only shape (autoPostHours /
     * scheduleHours) so a site that saved a window before units existed keeps
     * the value it chose instead of silently reverting to the default.
     *
     * @param array  $stored  the missedSchedule branch
     * @param string $key     'autoPost' or 'schedule'
     * @param array  $default fallback window
     *
     * @return array{every: float, unit: string}
     */
    public static function readWindow($stored, $key, $default)
    {
        if (isset($stored[$key]['every'], $stored[$key]['unit'])) {
            return [
                'every' => (float) $stored[$key]['every'],
                'unit'  => \in_array($stored[$key]['unit'], self::WINDOW_UNITS, true)
                    ? $stored[$key]['unit']
                    : $default['unit'],
            ];
        }

        $legacyKey = $key . 'Hours';

        if (isset($stored[$legacyKey])) {
            return ['every' => (float) $stored[$legacyKey], 'unit' => 'hour'];
        }

        return $default;
    }

    /**
     * A window in seconds, clamped to MAX_WINDOW_SECONDS. Zero (or less) means
     * "never give up", which callers read as "no threshold".
     *
     * @param array $window
     *
     * @return int
     */
    public static function windowSeconds($window)
    {
        $every = isset($window['every']) ? (float) $window['every'] : 0;
        $unit = isset($window['unit']) ? $window['unit'] : 'hour';

        if ($every <= 0 || !isset(self::DELAY_UNITS[$unit])) {
            return 0;
        }

        return (int) min(self::MAX_WINDOW_SECONDS, round($every * self::DELAY_UNITS[$unit]));
    }

    /**
     * Put back a one-shot's cron event when the event is gone and its time has
     * not come yet.
     *
     * A recurring schedule survives losing its event — register() writes it
     * again on the next load. A one-shot had nothing doing that for it, so any
     * event that went missing took the post with it: the row sat ACTIVE until
     * the reaper wrote it off. Deactivating the plugin is the ordinary way to
     * lose one (deactivation clears every schedule's events, and reactivating
     * only ever restored the recurring ones), but a cron array wiped by another
     * plugin or rolled back with a database restore does the same thing.
     *
     * Only ever forward: a slot that has already passed belongs to the reaper,
     * which decides whether it is still worth publishing. So this cannot post
     * anything late, and cannot post anything twice — an event that is still
     * queued is left exactly where it is.
     *
     * @param array $schedule
     * @param array $settings config.settings for that row
     */
    private function restoreSingleEvent($schedule, $settings)
    {
        if ($this->isRecurringRow($schedule, $settings)) {
            return;
        }

        $intendedAt = !empty($schedule['started_at'])
            ? $schedule['started_at']
            : (!empty($schedule['next_published_at']) ? $schedule['next_published_at'] : null);

        if (empty($intendedAt)) {
            return;
        }

        // The slot is WP-local wall-clock and a cron event is a real timestamp;
        // the delay between them is the only thing safe to carry across.
        $delay = strtotime($intendedAt) - strtotime(current_time('mysql'));

        if ($delay <= 0) {
            return;
        }

        if ($this->nextEventTimestamp($schedule['id'])) {
            return;
        }

        $actionHook = Config::VAR_PREFIX . $schedule['id'] . '_cron_exec';

        wp_schedule_single_event(time() + $delay, $actionHook, [['schedule_id' => $schedule['id']]]);
    }

    /**
     * How late this run actually is, in seconds.
     *
     * Two clocks answer that, and the kinder one wins. The slot the user picked
     * is one; the queue slot the event currently holds is the other, and they
     * differ whenever spaceOverdueBacklog() has pushed an event back to drain a
     * catch-up burst. Measuring only from the user's slot would write off
     * exactly the posts that deferral was protecting — the second post of a
     * burst is deferred by one spacing interval and would then be judged, and
     * killed, for having waited that interval.
     *
     * Each difference is taken inside its own clock: the slot is WP-local
     * wall-clock, the cron event is a real timestamp, and the two are never
     * subtracted from each other.
     *
     * @param string $intendedAt     WP-local wall-clock slot
     * @param int    $eventTimestamp pending cron event, 0 when none is queued
     * @param int    $nowWallClock   strtotime(current_time('mysql'))
     * @param int    $now            time()
     *
     * @return int
     */
    private function latenessOf($intendedAt, $eventTimestamp, $nowWallClock, $now)
    {
        $lateness = $nowWallClock - strtotime($intendedAt);

        if ($eventTimestamp > 0) {
            $lateness = min($lateness, $now - $eventTimestamp);
        }

        return (int) $lateness;
    }

    /**
     * When this install started watching for missed slots — the first time the
     * sweep ran, which is the first load after updating to the version that
     * introduced it.
     *
     * Anything older than that was already stuck before anyone was looking, and
     * is healed quietly rather than reported. Stored as WP-local wall-clock so
     * it compares directly against a schedule's slot.
     *
     * @return int
     */
    private static function reaperActiveSince()
    {
        $since = (int) Config::getOption('missed_reaper_since', 0);

        if ($since <= 0) {
            $since = strtotime(current_time('mysql'));
            Config::updateOption('missed_reaper_since', $since);
        }

        return $since;
    }

    /**
     * Fire the sweep's action once there is somebody to hear it.
     *
     * The sweep runs at plugins_loaded; the listeners are registered by the
     * providers at init 11 — Pro's missed-post email among them. Firing on the
     * spot would reach nobody at all, so a sweep that happens before init waits
     * for it.
     *
     * @param array $missedIds
     */
    private function announceMissed($missedIds)
    {
        $announce = static function () use ($missedIds) {
            Hooks::doAction(Config::withPrefix('schedules_missed'), $missedIds);
        };

        if (did_action('init')) {
            $announce();

            return;
        }

        Hooks::addAction('init', $announce, 20);
    }

    /**
     * Log the slot a written-off one-shot never got to fill.
     *
     * ScheduleInfo does the resolving rather than reading the row's config here,
     * so an account group expands the same way it would have on a real run and
     * the log names the accounts that were actually going to be posted to.
     *
     * @param int         $scheduleId
     * @param null|string $intendedAt the slot, WP-local wall-clock
     */
    private function logMissedSlot($scheduleId, $intendedAt)
    {
        $info = new ScheduleInfo(['schedule_id' => $scheduleId]);

        if (!$info->config()) {
            return;
        }

        $filters = $info->postFilters();
        $specificPostIds = !empty($filters['specific_postIds']) ? array_values($filters['specific_postIds']) : [];

        // A one-shot targets exactly one post (auto-post) or none at all (a
        // Share Now carries its own content), so there is no ordering to apply.
        $postId = isset($specificPostIds[0]) ? $specificPostIds[0] : null;

        (new MissedRunLogger())->log($scheduleId, $info->accounts(), $postId, $intendedAt);
    }

    /**
     * Whether a raw schedule row fires on a repeating cron event.
     *
     * Mirrors ScheduleInfo::isRecurring(), but works on the lightweight row
     * arrays this class holds rather than re-loading each schedule.
     *
     * @param array $schedule
     * @param array $settings config.settings for that row
     *
     * @return bool
     */
    private function isRecurringRow($schedule, $settings)
    {
        if ((int) $schedule['schedule_type'] === Schedule::scheduleType['DIRECT_SHARE']) {
            return !empty($settings['repeat']);
        }

        return !empty($settings['post_interval_value']) && !empty($settings['post_interval_type']);
    }

    /**
     * How long an overdue one-shot may sit before it is written off as MISSED.
     *
     * The two kinds of one-shot get separate windows, because they carry
     * different intent: an auto-post delay ("share 10 minutes after
     * publishing") is a spacing preference where late is still useful, while a
     * Share Now / scheduled share is a time the user deliberately chose.
     *
     * The shipped window is the same with or without a licence (see
     * DEFAULT_AUTOPOST_WINDOW) — an update must not quietly stop publishing on
     * sites whose cron has always been a quarter of an hour behind. What a
     * licence buys is the setting: raise the window, or set it to 0 and publish
     * however late. A stored value stops applying when the licence lapses, so
     * the site falls back to the shipped window rather than to an unlicensed
     * setting.
     *
     * Both are filterable per schedule; return <= 0 to never write that kind off.
     *
     * @param array $schedule
     * @param array $settings config.settings for that row
     *
     * @return int seconds
     */
    private function missedThresholdFor($schedule, $settings)
    {
        $isAutoPost = self::isAutoPostSchedule($schedule, $settings);

        $filter = $isAutoPost ? 'missed_autopost_threshold' : 'missed_schedule_threshold';
        $default = $isAutoPost ? self::DEFAULT_AUTOPOST_WINDOW : self::DEFAULT_SCHEDULE_WINDOW;
        $seconds = self::windowSeconds($default);

        if (Config::isProActivated()) {
            $saved = Config::getOption('settings', []);
            $stored = isset($saved['missedSchedule']) ? $saved['missedSchedule'] : [];
            $seconds = self::windowSeconds(self::readWindow($stored, $isAutoPost ? 'autoPost' : 'schedule', $default));
        }

        return (int) apply_filters(Config::VAR_PREFIX . $filter, $seconds, $schedule['id']);
    }

    private function setScheduleConfig($config)
    {
        $schedule = [];
        $config = \is_string($config) ? json_decode($config, true) : $config;

        if (empty($config)) {
            return false;
        }
        $settings = isset($config['settings']) ? $config['settings'] : [];
        $schedule['settings'] = $settings;

        return $schedule;
    }
}
